# Generated from tools/data/rulebooks/cash_auction.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class CashAuction
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:aim, GameRoomRules.translate("The aim"),
            GameRoomRules.translate("Cash Auction combines simultaneous bidding with quiz questions for two to eight players, including bots. Each question has four choices and one correct answer. Everyone starts with 10000 points by default. Finish with the most points among the players still in the match. Black chests contain separate prizes and never change the winner."),
            GameRoomRules.translate("Each auction starts with a category draw and an opening payment from every remaining player. You bid against one another for the right to answer a question. A correct answer wins the whole pool; a wrong answer leaves it for a later auction.")),
          rule_section(:rounds, GameRoomRules.translate("Starting an auction"),
            GameRoomRules.translate("The wheel announces the question category. Every player still in the match then pays 10 points into the common pool. If you cannot afford this payment, you are permanently eliminated. Money already in the pool stays there."),
            GameRoomRules.translate("Bidding is simultaneous: you do not wait for a turn. The bid field has focus when the auction starts. Enter an amount and press Enter to make an offer. An accepted offer clears the field; an invalid one leaves your text so you can correct it. The current question round, pool, highest offer and leading player are announced."),
            GameRoomRules.translate("After a bid, the auctioneer calls once, twice and three times, normally three seconds apart. Bidding stays open for one more interval after the third call; only Sold ends it. Every higher offer starts the calls afresh. With the default interval, an auction closes after twelve seconds without a new bid. If nobody bids, the pool carries over."),
            GameRoomRules.translate("P reads the pool. T explains whose decision is pending; during bidding, all eligible players may bid at once. H reads who is bidding and who has passed. D reads your points, and Shift+D reads the other players\u2019 points.")),
          rule_section(:bidding, GameRoomRules.translate("What an offer costs"),
            GameRoomRules.translate("Your offer is the total amount you commit to this auction, in addition to the opening payment. Every offer, including all-in, must beat the current highest offer. Every bidder pays immediately, including players who later lose the auction or pass; those payments are not refunded."),
            GameRoomRules.translate("When you raise your own offer, pay only the difference. For example, after offering 100, raising to 250 costs another 150. You may commit at most your remaining balance plus what you have already paid in bids this auction."),
            GameRoomRules.translate("To go all-in while you still have points, type A in the bid field and press Enter. You commit every remaining point, with earlier bid payments this auction counted in the total offer. You can also type that total amount instead of A. If this total beats the highest offer, all-in immediately closes the auction and wins the question or black chest. Nobody can raise after it. If your available total is no higher than the leading offer, you cannot bid or go all-in."),
            GameRoomRules.translate("The highest bidder cannot withdraw: their offer is binding. They can still raise their own offer before the close. The last accepted highest offer wins when the auction is closed. A bid reaching the game after the deadline is refused, even if the closing announcement has not finished speaking.")),
          rule_section(:passing, GameRoomRules.translate("Passing and inactivity penalties"),
            GameRoomRules.translate("If you are not leading, use Tab to reach Withdraw from this auction and press Enter. This is optional: it stops further bidding by you in this auction, but does not end the auction early. You may bid again in the next auction. Earlier payments stay in the pool."),
            GameRoomRules.translate("An auction in which you make no bid counts towards a run of missed auctions, whether you press Pass or simply do not bid. The opening payment does not count as a bid. After three consecutive auctions without a bid, you pay 200 points into the pool when the third auction closes, then the count returns to zero. If you have fewer than 200 points left, pay only that balance. Any accepted bid resets your count, even if you later lose that auction or pass.")),
          rule_section(:question, GameRoomRules.translate("Answering the question"),
            GameRoomRules.translate("After the auction, everyone can read the question and its four answers, A to D, but only the auction winner can answer. The question is a read-only text field. Press Down to reach the answer list, choose with the arrows and press Enter to submit. There is no answer time limit."),
            GameRoomRules.translate("A correct answer transfers the entire pool to the winner of the auction and starts a new pool at zero. A wrong answer leaves the whole pool for the next auction. If you went all-in and answer wrongly with nothing left, you are permanently eliminated."),
            GameRoomRules.translate("Before answering, the auction winner may buy one hint to remove two wrong choices. The price is 10% of their remaining points, rounded up, with a minimum of one point; the button shows the exact cost. The payment leaves the game rather than entering the pool. With no points left, a hint cannot be bought.")),
          rule_section(:chests, GameRoomRules.translate("Black chests"),
            GameRoomRules.translate("A black chest replaces the category and question on 10% of spins by default. Bid for it normally. Its winner keeps it unopened, while the pool carries over. Chest auctions do not count towards the question limit."),
            GameRoomRules.translate("At the end, every owner opens their chests, including eliminated players. Use Open a black chest for each one. A chest gives an additional prize of 100, 500, 1000, 2500, 5000, 7500 or 10000, with equal chances. These prizes do not change points, elimination or the match winner. Chests contain no deductions or bankruptcy.")),
          rule_section(:finish, GameRoomRules.translate("The end of the match"),
            GameRoomRules.translate("A normal match lasts eight answered questions, right or wrong. Chest auctions and auctions without bids do not count. The match also ends when at most one player remains. Everyone opens their chests before the final result is announced, but the prizes cannot change the standings."),
            GameRoomRules.translate("After all chests are open, the remaining player with the most points wins. If several remaining players share the highest balance, play on until another question has been answered, with every player still in the match taking part, not just the tied leaders. Chest auctions and auctions with no bids do not finish this extra question round. Open any new chests before comparing balances again, and repeat if necessary. If no players remain, the match is a draw."),
            GameRoomRules.translate("S reads everyone\u2019s balances and unopened chest counts outside the auction, including while a question is on screen. Use Shift+S during bidding.")),
          rule_section(:settings, GameRoomRules.translate("Table settings"),
            GameRoomRules.translate("Before starting, choose the question language and select two or three Quiz sets in the table settings. Mark the sets you want with Space and confirm the selection with Enter. Their questions and categories are combined for this match. If that language has only one available set, use that one; the English and Russian catalogues currently have one each. The question language can differ from the interface language."),
            GameRoomRules.translate("You can change the starting balance from 10000 to any whole number from 10 to 1000000. The opening payment can be from 1 point up to that starting balance. The penalty after three consecutive auctions without a bid can be from 0 to 1000000; zero disables the deduction, while passing still withdraws you from that auction."),
            GameRoomRules.translate("Choose 8\u201332 answered questions and 1\u20135 seconds between calls. By default there are eight questions and three seconds between calls. Without all-in, the auction closes after four intervals without a higher offer, leaving one interval after the third call. The black-chest chance is adjustable from 5% to 15%, with 10% as the default.")),
          rule_section(:controls, GameRoomRules.translate("Controls"),
            GameRoomRules.translate("Enter in the bid field: submit the amount you typed."),
            GameRoomRules.translate("A: type A in the bid field, then press Enter to go all-in if your total exceeds the highest offer and win the auction immediately."),
            GameRoomRules.translate("Tab: reach Withdraw from this auction."),
            GameRoomRules.translate("Down from the question: move to the answers. Arrows select an answer; Enter submits it if you won the auction."),
            GameRoomRules.translate("Enter on Open a black chest: open one of your chests."),
            GameRoomRules.translate("S: outside bidding, read balances and unopened chests."),
            GameRoomRules.translate("Shift+S: during bidding, read balances and unopened chests."),
            GameRoomRules.translate("P: read the pool."),
            GameRoomRules.translate("T: read whose decision is pending."),
            GameRoomRules.translate("H: read who is bidding and who has passed."),
            GameRoomRules.translate("D: read your points."),
            GameRoomRules.translate("Shift+D: read the other players\u2019 points."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "C\u00EDl hry",
              "Dra\u017Eba kombinuje sou\u010Dasn\u00E9 p\u0159ihazov\u00E1n\u00ED s kv\u00EDzem pro dva a\u017E osm hr\u00E1\u010D\u016F v\u010Detn\u011B bot\u016F. Ka\u017Ed\u00E1 ot\u00E1zka m\u00E1 \u010Dty\u0159i odpov\u011Bdi a jednu spr\u00E1vnou. B\u011B\u017En\u011B za\u010D\u00EDn\u00E1te s 10000 body. Vyhr\u00E1v\u00E1 nejvy\u0161\u0161\u00ED sk\u00F3re mezi hr\u00E1\u010Di, kte\u0159\u00ED z\u016Fstali ve h\u0159e. \u010Cern\u00E9 truhly obsahuj\u00ED samostatn\u00E9 v\u00FDhry a v\u00EDt\u011Bze nem\u011Bn\u00ED.",
              "Ka\u017Ed\u00E1 aukce za\u010D\u00EDn\u00E1 vylosov\u00E1n\u00EDm kategorie a povinn\u00FDm vkladem v\u0161ech zb\u00FDvaj\u00EDc\u00EDch hr\u00E1\u010D\u016F. Potom dra\u017E\u00EDte pr\u00E1vo odpov\u011Bd\u011Bt na ot\u00E1zku. Za spr\u00E1vnou odpov\u011B\u010F z\u00EDsk\u00E1\u0161 cel\u00FD bank, po chybn\u00E9 odpov\u011Bdi se bank p\u0159ev\u00E1d\u00ED do dal\u0161\u00ED aukce."),
            rule_section(:rounds, "Za\u010D\u00E1tek aukce",
              "Kolo \u0161t\u011Bst\u00ED ozn\u00E1m\u00ED kategorii ot\u00E1zky. Ka\u017Ed\u00FD hr\u00E1\u010D, kter\u00FD je dosud ve h\u0159e, vlo\u017E\u00ED do spole\u010Dn\u00E9ho banku 10 bod\u016F. Kdo na vklad nem\u00E1, je trvale vy\u0159azen. Body, kter\u00E9 u\u017E v banku jsou, v n\u011Bm z\u016Fst\u00E1vaj\u00ED.",
              "Nab\u00EDdky pod\u00E1v\u00E1te sou\u010Dasn\u011B, ne\u010Dek\u00E1te na tah. P\u0159i zah\u00E1jen\u00ED aukce je kurzor v poli pro \u010D\u00E1stku. Napi\u0161 nab\u00EDdku a potvr\u010F ji Enterem. P\u0159ijat\u00E1 nab\u00EDdka pole vyma\u017Ee; po neplatn\u00E9 z\u016Fstane text k oprav\u011B. Usly\u0161\u00ED\u0161 \u010D\u00EDslo kola s ot\u00E1zkou, v\u00FD\u0161i banku, nejvy\u0161\u0161\u00ED nab\u00EDdku a jm\u00E9no vedouc\u00EDho hr\u00E1\u010De.",
              "Po nab\u00EDdce vyvol\u00E1va\u010D vol\u00E1 poprv\u00E9, podruh\u00E9 a pot\u0159et\u00ED, b\u011B\u017En\u011B po t\u0159ech sekund\u00E1ch. Po t\u0159et\u00EDm vyvol\u00E1n\u00ED z\u016Fst\u00E1v\u00E1 je\u0161t\u011B jeden interval na nab\u00EDdku; a\u017E p\u0159iklepnut\u00ED dra\u017Ebu uzav\u0159e. Ka\u017Ed\u00E9 zv\u00FD\u0161en\u00ED spust\u00ED vol\u00E1n\u00ED znovu. P\u0159i v\u00FDchoz\u00EDm nastaven\u00ED se dra\u017Eba uzav\u0159e po dvan\u00E1cti sekund\u00E1ch bez nov\u00E9 nab\u00EDdky. Bez nab\u00EDdky se bank p\u0159ev\u00E1d\u00ED d\u00E1l.",
              "P p\u0159e\u010Dte bank. T ozn\u00E1m\u00ED, kdo m\u016F\u017Ee jednat; b\u011Bhem aukce mohou v\u0161ichni opr\u00E1vn\u011Bn\u00ED hr\u00E1\u010Di p\u0159ihazovat sou\u010Dasn\u011B. H p\u0159e\u010Dte, kdo p\u0159ihazuje a kdo odstoupil. D p\u0159e\u010Dte tv\u00E9 body a Shift+D body ostatn\u00EDch hr\u00E1\u010D\u016F."),
            rule_section(:bidding, "Kolik stoj\u00ED nab\u00EDdka",
              "Nab\u00EDdka ud\u00E1v\u00E1 celkovou \u010D\u00E1stku, kterou d\u00E1v\u00E1\u0161 do t\u00E9to aukce nav\u00EDc k po\u010D\u00E1te\u010Dn\u00EDmu vkladu. Ka\u017Ed\u00E1 nab\u00EDdka, i s\u00E1zka v\u0161ech bod\u016F, mus\u00ED p\u0159ev\u00FD\u0161it dosud nejvy\u0161\u0161\u00ED nab\u00EDdku. Ka\u017Ed\u00FD dra\u017E\u00EDc\u00ED plat\u00ED okam\u017Eit\u011B. Body se nevracej\u00ED ani hr\u00E1\u010D\u016Fm, kte\u0159\u00ED pozd\u011Bji aukci prohraj\u00ED nebo odstoup\u00ED.",
              "P\u0159i zv\u00FD\u0161en\u00ED vlastn\u00ED nab\u00EDdky doplat\u00ED\u0161 pouze rozd\u00EDl. Po nab\u00EDdce 100 tedy zv\u00FD\u0161en\u00ED na 250 stoj\u00ED dal\u0161\u00EDch 150. Nab\u00EDdnout m\u016F\u017Ee\u0161 nejv\u00FD\u0161e sou\u010Det zb\u00FDvaj\u00EDc\u00EDch bod\u016F a bod\u016F, kter\u00E9 u\u017E jsi v t\u00E9to aukci zaplatil za nab\u00EDdky.",
              "Pokud ti je\u0161t\u011B zb\u00FDvaj\u00ED body, m\u016F\u017Ee\u0161 vsadit v\u0161e: do pole \u010D\u00E1stky napi\u0161 A a stiskni Enter. Vsad\u00ED\u0161 v\u0161echny zb\u00FDvaj\u00EDc\u00ED body; platby za d\u0159\u00EDv\u011Bj\u0161\u00ED nab\u00EDdky v t\u00E9to aukci se p\u0159i\u010Dtou k celkov\u00E9 \u010D\u00E1stce. M\u00EDsto A m\u016F\u017Ee\u0161 zadat i tuto celkovou \u010D\u00E1stku. Pokud p\u0159ev\u00FD\u0161\u00ED nejvy\u0161\u0161\u00ED nab\u00EDdku, aukci okam\u017Eit\u011B ukon\u010D\u00ED\u0161 a z\u00EDsk\u00E1\u0161 ot\u00E1zku nebo \u010Dernou truhlu. Nikdo u\u017E nem\u016F\u017Ee p\u0159ihodit. Jestli\u017Ee tv\u00E1 dostupn\u00E1 celkov\u00E1 \u010D\u00E1stka nen\u00ED vy\u0161\u0161\u00ED ne\u017E vedouc\u00ED nab\u00EDdka, nem\u016F\u017Ee\u0161 p\u0159ihodit ani vsadit v\u0161e.",
              "Vedouc\u00ED dra\u017Eitel nem\u016F\u017Ee odstoupit, jeho nab\u00EDdka je z\u00E1vazn\u00E1. P\u0159ed uzav\u0159en\u00EDm ji ale m\u016F\u017Ee zv\u00FD\u0161it. Vyhr\u00E1v\u00E1 posledn\u00ED p\u0159ijat\u00E1 nejvy\u0161\u0161\u00ED nab\u00EDdka. Nab\u00EDdka doru\u010Den\u00E1 po term\u00EDnu se odm\u00EDtne, i kdy\u017E hlas je\u0161t\u011B do\u010D\u00EDt\u00E1 z\u00E1v\u011Bre\u010Dn\u00E9 ozn\u00E1men\u00ED."),
            rule_section(:passing, "Odstoupen\u00ED a pokuta za ne\u00FA\u010Dast v dra\u017Eb\u011B",
              "Pokud nevede\u0161, p\u0159ejdi Tabem na Odstoupit z t\u00E9to dra\u017Eby a stiskni Enter. Je to voliteln\u00E9: zablokuje to tv\u00E9 dal\u0161\u00ED nab\u00EDdky jen v t\u00E9to dra\u017Eb\u011B a neukon\u010D\u00ED ji d\u0159\u00EDve. V p\u0159\u00ED\u0161t\u00ED m\u016F\u017Ee\u0161 op\u011Bt p\u0159ihazovat. P\u0159edchoz\u00ED platby z\u016Fst\u00E1vaj\u00ED v banku.",
              "Aukce, ve kter\u00E9 nepod\u00E1\u0161 \u017E\u00E1dnou nab\u00EDdku, se zapo\u010D\u00EDt\u00E1 do \u0159ady aukc\u00ED bez vlastn\u00ED nab\u00EDdky. Nez\u00E1le\u017E\u00ED na tom, zda stiskne\u0161 Pas, nebo v\u016Fbec nep\u0159ihod\u00ED\u0161. Po\u010D\u00E1te\u010Dn\u00ED vklad se za nab\u00EDdku nepova\u017Euje. Po t\u0159ech takov\u00FDch aukc\u00EDch za sebou zaplat\u00ED\u0161 p\u0159i uzav\u0159en\u00ED t\u0159et\u00ED aukce do banku 200 bod\u016F a po\u010D\u00EDtadlo se vynuluje. Zb\u00FDv\u00E1-li ti m\u00E9n\u011B ne\u017E 200 bod\u016F, zaplat\u00ED\u0161 jen zb\u00FDvaj\u00EDc\u00ED z\u016Fstatek. Ka\u017Ed\u00E1 p\u0159ijat\u00E1 nab\u00EDdka po\u010D\u00EDtadlo vynuluje, i kdy\u017E pak aukci prohraje\u0161 nebo odstoup\u00ED\u0161."),
            rule_section(:question, "Odpov\u011B\u010F na ot\u00E1zku",
              "Po aukci si v\u0161ichni mohou p\u0159e\u010D\u00EDst ot\u00E1zku a odpov\u011Bdi A a\u017E D, odpov\u00EDdat v\u0161ak m\u016F\u017Ee jen v\u00EDt\u011Bz aukce. Ot\u00E1zka je v textov\u00E9m poli pouze pro \u010Dten\u00ED. \u0160ipkou dol\u016F p\u0159ejdi na seznam odpov\u011Bd\u00ED, \u0161ipkami vyber mo\u017Enost a potvr\u010F Enterem. Na odpov\u011B\u010F nen\u00ED \u010Dasov\u00FD limit.",
              "Za spr\u00E1vnou odpov\u011B\u010F dostane v\u00EDt\u011Bz aukce cel\u00FD bank a nov\u00FD bank za\u010D\u00EDn\u00E1 na nule. Po chybn\u00E9 odpov\u011Bdi se v\u0161e p\u0159evede do dal\u0161\u00ED aukce. Pokud jsi vsadil v\u0161e a po chybn\u00E9 odpov\u011Bdi nem\u00E1\u0161 \u017E\u00E1dn\u00E9 body, jsi trvale vy\u0159azen.",
              "P\u0159ed odpov\u011Bd\u00ED si v\u00EDt\u011Bz dra\u017Eby m\u016F\u017Ee jednou koupit n\u00E1pov\u011Bdu odstra\u0148uj\u00EDc\u00ED dv\u011B chybn\u00E9 mo\u017Enosti. Stoj\u00ED 10 % jeho zb\u00FDvaj\u00EDc\u00EDch bod\u016F, zaokrouhleno nahoru, nejm\u00E9n\u011B jeden bod; tla\u010D\u00EDtko uv\u00E1d\u00ED p\u0159esnou cenu. Platba se nevrac\u00ED do banku. Bez bod\u016F n\u00E1pov\u011Bdu koupit nelze."),
            rule_section(:chests, "\u010Cern\u00E9 truhly",
              "Ve v\u00FDchoz\u00EDm nastaven\u00ED nahrad\u00ED \u010Dern\u00E1 truhla kategorii a ot\u00E1zku p\u0159i 10 % losov\u00E1n\u00ED. Dra\u017E\u00ED se obvykl\u00FDm zp\u016Fsobem. V\u00EDt\u011Bz si ji nech\u00E1 zav\u0159enou a bank se p\u0159ev\u00E1d\u00ED. Dra\u017Eby truhel se nepo\u010D\u00EDtaj\u00ED do limitu ot\u00E1zek.",
              "Na konci ka\u017Ed\u00FD otev\u0159e sv\u00E9 truhly, i vy\u0159azen\u00ED hr\u00E1\u010Di. Pro ka\u017Edou zvol Otev\u0159\u00EDt \u010Dernou truhlu. Obsahuje dodate\u010Dnou v\u00FDhru 100, 500, 1000, 2500, 5000, 7500 nebo 10000, v\u0161echny stejn\u011B pravd\u011Bpodobn\u00E9. V\u00FDhry nem\u011Bn\u00ED sk\u00F3re, vy\u0159azen\u00ED ani v\u00EDt\u011Bze hry. Truhly neobsahuj\u00ED ztr\u00E1ty ani bankrot."),
            rule_section(:finish, "Konec z\u00E1pasu",
              "B\u011B\u017En\u00E1 hra m\u00E1 osm zodpov\u011Bzen\u00FDch ot\u00E1zek, spr\u00E1vn\u011B \u010Di chybn\u011B. Truhly a dra\u017Eby bez nab\u00EDdek se nepo\u010D\u00EDtaj\u00ED. Hra kon\u010D\u00ED tak\u00E9 p\u0159i nejv\u00FD\u0161e jednom zb\u00FDvaj\u00EDc\u00EDm hr\u00E1\u010Di. P\u0159ed ozn\u00E1men\u00EDm v\u00FDsledku v\u0161ichni otev\u0159ou truhly, jejich\u017E v\u00FDhry po\u0159ad\u00ED nem\u011Bn\u00ED.",
              "Po otev\u0159en\u00ED v\u0161ech truhel vyhr\u00E1v\u00E1 hr\u00E1\u010D s nejv\u00EDce body z t\u011Bch, kte\u0159\u00ED z\u016Fstali ve h\u0159e. M\u00E1-li n\u011Bkolik zb\u00FDvaj\u00EDc\u00EDch hr\u00E1\u010D\u016F stejn\u00FD nejvy\u0161\u0161\u00ED z\u016Fstatek, hraje se a\u017E do zodpov\u011Bzen\u00ED dal\u0161\u00ED ot\u00E1zky se v\u0161emi zb\u00FDvaj\u00EDc\u00EDmi hr\u00E1\u010Di, nejen s vedouc\u00EDmi. Aukce truhel ani aukce bez nab\u00EDdek tuto dohr\u00E1vku neukon\u010D\u00ED. P\u0159ed dal\u0161\u00EDm porovn\u00E1n\u00EDm otev\u0159ete i nov\u011B z\u00EDskan\u00E9 truhly; podle pot\u0159eby se dohr\u00E1vka opakuje. Nez\u016Fstane-li nikdo ve h\u0159e, z\u00E1pas kon\u010D\u00ED rem\u00EDzou.",
              "Mimo aukci p\u0159e\u010Dte S z\u016Fstatky v\u0161ech hr\u00E1\u010D\u016F a po\u010Dty jejich neotev\u0159en\u00FDch truhel, tak\u00E9 b\u011Bhem ot\u00E1zky. P\u0159i dra\u017Een\u00ED pou\u017Eij Shift+S."),
            rule_section(:settings, "Nastaven\u00ED stolu",
              "P\u0159ed za\u010D\u00E1tkem vyber v nastaven\u00ED stolu jazyk ot\u00E1zek a dv\u011B nebo t\u0159i sady Kv\u00EDzu. Mezern\u00EDkem ozna\u010D po\u017Eadovan\u00E9 sady a Enterem v\u00FDb\u011Br potvr\u010F. Jejich ot\u00E1zky a kategorie se pro tento z\u00E1pas spoj\u00ED. Je-li pro zvolen\u00FD jazyk dostupn\u00E1 jen jedna sada, pou\u017Eije se tato sada; nyn\u00ED to plat\u00ED pro angli\u010Dtinu a ru\u0161tinu. Jazyk ot\u00E1zek se m\u016F\u017Ee li\u0161it od jazyka rozhran\u00ED.",
              "M\u00EDsto po\u010D\u00E1te\u010Dn\u00EDch 10000 bod\u016F lze nastavit cel\u00E9 \u010D\u00EDslo od 10 do 1000000. Povinn\u00FD vklad na za\u010D\u00E1tku aukce m\u016F\u017Ee b\u00FDt od 1 bodu a\u017E po cel\u00FD po\u010D\u00E1te\u010Dn\u00ED z\u016Fstatek. Pokuta po t\u0159ech aukc\u00EDch za sebou bez vlastn\u00ED nab\u00EDdky m\u016F\u017Ee b\u00FDt od 0 do 1000000. Nula vypne ode\u010Det, ale odstoupen\u00ED t\u011B i nad\u00E1le vy\u0159ad\u00ED z pr\u00E1v\u011B prob\u00EDhaj\u00EDc\u00ED aukce.",
              "Lze zvolit 8 a\u017E 32 ot\u00E1zek a 1 a\u017E 5 sekund mezi vyvol\u00E1n\u00EDmi. V\u00FDchoz\u00ED hodnoty jsou osm ot\u00E1zek a t\u0159i sekundy. Bez s\u00E1zky v\u0161eho se dra\u017Eba uzav\u0159e po \u010Dty\u0159ech intervalech bez zv\u00FD\u0161en\u00ED, s jedn\u00EDm intervalem po t\u0159et\u00EDm vyvol\u00E1n\u00ED. \u0160anci na \u010Dernou truhlu lze nastavit od 5 do 15 %, v\u00FDchoz\u00ED je 10 %."),
            rule_section(:controls, "Ovl\u00E1d\u00E1n\u00ED",
              "Enter v poli \u010D\u00E1stky: odeslat napsanou nab\u00EDdku.",
              "A: do pole \u010D\u00E1stky napi\u0161 A a stiskni Enter. Pokud tv\u00E1 celkov\u00E1 \u010D\u00E1stka p\u0159ev\u00FD\u0161\u00ED nejvy\u0161\u0161\u00ED nab\u00EDdku, vsad\u00ED\u0161 v\u0161e a okam\u017Eit\u011B vyhraje\u0161 aukci.",
              "Tab: p\u0159ejdi na Odstoupit z t\u00E9to dra\u017Eby.",
              "\u0160ipka dol\u016F z ot\u00E1zky: p\u0159ej\u00EDt k odpov\u011Bd\u00EDm. \u0160ipky vyb\u00EDraj\u00ED mo\u017Enost, Enter ji ode\u0161le, pokud jsi vyhr\u00E1l aukci.",
              "Enter na tla\u010D\u00EDtku Otev\u0159\u00EDt \u010Dernou truhlu: otev\u0159\u00EDt jednu vlastn\u00ED truhlu.",
              "S: mimo dra\u017Ebu p\u0159e\u010Dti sk\u00F3re a zav\u0159en\u00E9 truhly.",
              "Shift+S: b\u011Bhem dra\u017Eby p\u0159e\u010Dti sk\u00F3re a zav\u0159en\u00E9 truhly.",
              "P: p\u0159e\u010D\u00EDst bank.",
              "T: p\u0159e\u010D\u00EDst, kdo m\u016F\u017Ee jednat.",
              "H: p\u0159e\u010D\u00EDst, kdo p\u0159ihazuje a kdo odstoupil.",
              "D: p\u0159e\u010D\u00EDst vlastn\u00ED body.",
              "Shift+D: p\u0159e\u010D\u00EDst body ostatn\u00EDch hr\u00E1\u010D\u016F.")
          ]
        when "en"
          [
            rule_section(:aim, "The aim",
              "Cash Auction combines simultaneous bidding with quiz questions for two to eight players, including bots. Each question has four choices and one correct answer. Everyone starts with 10000 points by default. Finish with the most points among the players still in the match. Black chests contain separate prizes and never change the winner.",
              "Each auction starts with a category draw and an opening payment from every remaining player. You bid against one another for the right to answer a question. A correct answer wins the whole pool; a wrong answer leaves it for a later auction."),
            rule_section(:rounds, "Starting an auction",
              "The wheel announces the question category. Every player still in the match then pays 10 points into the common pool. If you cannot afford this payment, you are permanently eliminated. Money already in the pool stays there.",
              "Bidding is simultaneous: you do not wait for a turn. The bid field has focus when the auction starts. Enter an amount and press Enter to make an offer. An accepted offer clears the field; an invalid one leaves your text so you can correct it. The current question round, pool, highest offer and leading player are announced.",
              "After a bid, the auctioneer calls once, twice and three times, normally three seconds apart. Bidding stays open for one more interval after the third call; only Sold ends it. Every higher offer starts the calls afresh. With the default interval, an auction closes after twelve seconds without a new bid. If nobody bids, the pool carries over.",
              "P reads the pool. T explains whose decision is pending; during bidding, all eligible players may bid at once. H reads who is bidding and who has passed. D reads your points, and Shift+D reads the other players\u2019 points."),
            rule_section(:bidding, "What an offer costs",
              "Your offer is the total amount you commit to this auction, in addition to the opening payment. Every offer, including all-in, must beat the current highest offer. Every bidder pays immediately, including players who later lose the auction or pass; those payments are not refunded.",
              "When you raise your own offer, pay only the difference. For example, after offering 100, raising to 250 costs another 150. You may commit at most your remaining balance plus what you have already paid in bids this auction.",
              "To go all-in while you still have points, type A in the bid field and press Enter. You commit every remaining point, with earlier bid payments this auction counted in the total offer. You can also type that total amount instead of A. If this total beats the highest offer, all-in immediately closes the auction and wins the question or black chest. Nobody can raise after it. If your available total is no higher than the leading offer, you cannot bid or go all-in.",
              "The highest bidder cannot withdraw: their offer is binding. They can still raise their own offer before the close. The last accepted highest offer wins when the auction is closed. A bid reaching the game after the deadline is refused, even if the closing announcement has not finished speaking."),
            rule_section(:passing, "Passing and inactivity penalties",
              "If you are not leading, use Tab to reach Withdraw from this auction and press Enter. This is optional: it stops further bidding by you in this auction, but does not end the auction early. You may bid again in the next auction. Earlier payments stay in the pool.",
              "An auction in which you make no bid counts towards a run of missed auctions, whether you press Pass or simply do not bid. The opening payment does not count as a bid. After three consecutive auctions without a bid, you pay 200 points into the pool when the third auction closes, then the count returns to zero. If you have fewer than 200 points left, pay only that balance. Any accepted bid resets your count, even if you later lose that auction or pass."),
            rule_section(:question, "Answering the question",
              "After the auction, everyone can read the question and its four answers, A to D, but only the auction winner can answer. The question is a read-only text field. Press Down to reach the answer list, choose with the arrows and press Enter to submit. There is no answer time limit.",
              "A correct answer transfers the entire pool to the winner of the auction and starts a new pool at zero. A wrong answer leaves the whole pool for the next auction. If you went all-in and answer wrongly with nothing left, you are permanently eliminated.",
              "Before answering, the auction winner may buy one hint to remove two wrong choices. The price is 10% of their remaining points, rounded up, with a minimum of one point; the button shows the exact cost. The payment leaves the game rather than entering the pool. With no points left, a hint cannot be bought."),
            rule_section(:chests, "Black chests",
              "A black chest replaces the category and question on 10% of spins by default. Bid for it normally. Its winner keeps it unopened, while the pool carries over. Chest auctions do not count towards the question limit.",
              "At the end, every owner opens their chests, including eliminated players. Use Open a black chest for each one. A chest gives an additional prize of 100, 500, 1000, 2500, 5000, 7500 or 10000, with equal chances. These prizes do not change points, elimination or the match winner. Chests contain no deductions or bankruptcy."),
            rule_section(:finish, "The end of the match",
              "A normal match lasts eight answered questions, right or wrong. Chest auctions and auctions without bids do not count. The match also ends when at most one player remains. Everyone opens their chests before the final result is announced, but the prizes cannot change the standings.",
              "After all chests are open, the remaining player with the most points wins. If several remaining players share the highest balance, play on until another question has been answered, with every player still in the match taking part, not just the tied leaders. Chest auctions and auctions with no bids do not finish this extra question round. Open any new chests before comparing balances again, and repeat if necessary. If no players remain, the match is a draw.",
              "S reads everyone\u2019s balances and unopened chest counts outside the auction, including while a question is on screen. Use Shift+S during bidding."),
            rule_section(:settings, "Table settings",
              "Before starting, choose the question language and select two or three Quiz sets in the table settings. Mark the sets you want with Space and confirm the selection with Enter. Their questions and categories are combined for this match. If that language has only one available set, use that one; the English and Russian catalogues currently have one each. The question language can differ from the interface language.",
              "You can change the starting balance from 10000 to any whole number from 10 to 1000000. The opening payment can be from 1 point up to that starting balance. The penalty after three consecutive auctions without a bid can be from 0 to 1000000; zero disables the deduction, while passing still withdraws you from that auction.",
              "Choose 8\u201332 answered questions and 1\u20135 seconds between calls. By default there are eight questions and three seconds between calls. Without all-in, the auction closes after four intervals without a higher offer, leaving one interval after the third call. The black-chest chance is adjustable from 5% to 15%, with 10% as the default."),
            rule_section(:controls, "Controls",
              "Enter in the bid field: submit the amount you typed.",
              "A: type A in the bid field, then press Enter to go all-in if your total exceeds the highest offer and win the auction immediately.",
              "Tab: reach Withdraw from this auction.",
              "Down from the question: move to the answers. Arrows select an answer; Enter submits it if you won the auction.",
              "Enter on Open a black chest: open one of your chests.",
              "S: outside bidding, read balances and unopened chests.",
              "Shift+S: during bidding, read balances and unopened chests.",
              "P: read the pool.",
              "T: read whose decision is pending.",
              "H: read who is bidding and who has passed.",
              "D: read your points.",
              "Shift+D: read the other players\u2019 points.")
          ]
        when "es"
          [
            rule_section(:aim, "Objetivo del juego",
              "Subasta de dinero combina pujas simult\u00E1neas y preguntas para dos a ocho jugadores, incluidos bots. Cada pregunta tiene cuatro opciones y una correcta. Se empieza con 10000 puntos por defecto. Gana quien conserve m\u00E1s puntos entre quienes sigan en la partida. Los cofres negros contienen premios aparte y no cambian al ganador.",
              "Cada subasta empieza con el sorteo de una categor\u00EDa y una aportaci\u00F3n de todos los jugadores que sigan en juego. Despu\u00E9s puj\u00E1is por el derecho a responder. Acertar da todo el bote; un fallo lo deja para otra subasta."),
            rule_section(:rounds, "Comienzo de la subasta",
              "La ruleta anuncia la categor\u00EDa de la pregunta. Todos los jugadores que sigan en la partida aportan entonces 10 puntos al bote com\u00FAn. Quien no pueda pagar queda eliminado definitivamente. Los puntos que ya hubiera en el bote permanecen en \u00E9l.",
              "Las pujas son simult\u00E1neas: no tienes que esperar un turno. Al empezar la subasta, el foco est\u00E1 en el campo del importe. Escribe tu oferta y pulsa Intro. Una oferta aceptada vac\u00EDa el campo; si es inv\u00E1lida, el texto queda para que lo corrijas. Se anuncian la ronda de preguntas actual, el bote, la mayor oferta y el jugador que va ganando.",
              "Tras una oferta se anuncia a la de una, a la de dos y a la de tres, normalmente cada tres segundos. Despu\u00E9s del tercer aviso queda un intervalo m\u00E1s para pujar; solo la adjudicaci\u00F3n cierra la subasta. Cada subida reinicia los avisos. Por defecto se cierra tras doce segundos sin otra oferta. Si nadie puja, el bote se acumula.",
              "P anuncia el bote. T indica qui\u00E9n puede actuar; durante la subasta, todos los jugadores habilitados pueden pujar a la vez. H anuncia qui\u00E9n puja y qui\u00E9n ha pasado. D anuncia tus puntos y May\u00FAs+D los de los dem\u00E1s jugadores."),
            rule_section(:bidding, "Cu\u00E1nto cuesta una puja",
              "Tu oferta es el importe total que comprometes en esta subasta, aparte de la aportaci\u00F3n inicial. Todas las ofertas, tambi\u00E9n al ir con todo, deben superar la m\u00E1s alta. Todos los que pujan pagan en el acto, aunque despu\u00E9s pierdan la subasta o pasen; esos puntos no se devuelven.",
              "Al subir tu propia oferta solo pagas la diferencia. Si ofreciste 100, subir a 250 cuesta otros 150. Como m\u00E1ximo puedes ofrecer tu saldo restante m\u00E1s lo que ya hayas pagado en pujas durante esta subasta.",
              "Si todav\u00EDa te quedan puntos, puedes ir con todo: escribe A en el campo del importe y pulsa Intro. Comprometes todos los puntos restantes; lo ya pagado en pujas durante esta subasta se suma para formar la oferta total. Tambi\u00E9n puedes escribir ese importe total en vez de A. Si supera la mayor oferta, cierras la subasta al instante y ganas la pregunta o el cofre negro. Nadie puede volver a subirla. Si tu total disponible no supera la oferta que va ganando, no puedes pujar ni ir con todo.",
              "Quien va ganando no puede retirarse: su oferta es vinculante. Puede subirla antes del cierre. Gana la \u00FAltima oferta m\u00E1s alta aceptada. Se rechaza la que llegue despu\u00E9s del plazo, aunque a\u00FAn se est\u00E9 leyendo el anuncio de cierre."),
            rule_section(:passing, "Pasar y la penalizaci\u00F3n por no pujar",
              "Si no vas ganando, llega con Tab a Retirarse de esta subasta y pulsa Intro. Es opcional: impide que sigas pujando en esta subasta, pero no la termina antes. Puedes volver a pujar en la siguiente. Lo pagado permanece en el bote.",
              "Cada subasta en la que no haces ninguna oferta cuenta como una subasta sin participar, tanto si pulsas Pasar como si simplemente no pujas. La aportaci\u00F3n inicial no cuenta como oferta. Tras tres subastas seguidas sin pujar, pagas 200 puntos al bote cuando se cierra la tercera y la cuenta vuelve a cero. Si te quedan menos de 200 puntos, solo pagas ese saldo. Cualquier oferta aceptada reinicia la cuenta, aunque luego pierdas la subasta o pases."),
            rule_section(:question, "Responder a la pregunta",
              "Tras la subasta, todos pueden leer la pregunta y las respuestas A\u2013D, pero solo responde quien la haya ganado. La pregunta aparece en un campo de texto de solo lectura. Pulsa Abajo para ir a la lista, elige con las flechas y confirma con Intro. No hay l\u00EDmite de tiempo para responder.",
              "Si acierta, el ganador de la subasta recibe todo el bote y el nuevo bote empieza en cero. Si falla, se conserva todo para la siguiente subasta. Si fuiste con todo y tras el fallo no te quedan puntos, quedas eliminado definitivamente.",
              "Antes de responder, quien gane la subasta puede comprar una pista una vez para eliminar dos opciones incorrectas. Cuesta el 10 % de sus puntos restantes, redondeado hacia arriba, con un m\u00EDnimo de uno; el bot\u00F3n muestra el precio exacto. El pago sale del juego y no entra en el bote. Sin puntos no se puede comprar."),
            rule_section(:chests, "Cofres negros",
              "Por defecto, un cofre negro sustituye a la categor\u00EDa y la pregunta en el 10 % de los giros. Se puja normalmente. Quien gane lo conserva cerrado y el bote se acumula. Estas subastas no cuentan para el l\u00EDmite de preguntas.",
              "Al final todos abren sus cofres, incluso los jugadores eliminados. Usa Abrir un cofre negro para cada uno. Contienen un premio adicional de 100, 500, 1000, 2500, 5000, 7500 o 10000, con igual probabilidad. No cambian los puntos, las eliminaciones ni al ganador. No contienen p\u00E9rdidas ni bancarrota."),
            rule_section(:finish, "Final de la partida",
              "Una partida normal incluye ocho preguntas respondidas, bien o mal. No cuentan los cofres ni las subastas sin ofertas. Tambi\u00E9n termina si queda como m\u00E1ximo un jugador. Todos abren sus cofres antes del resultado final, pero sus premios no alteran la clasificaci\u00F3n.",
              "Despu\u00E9s de abrir todos los cofres, gana quien tenga m\u00E1s puntos entre los jugadores que sigan en la partida. Si varios comparten el saldo m\u00E1s alto, se sigue hasta responder otra pregunta con todos los que sigan en juego, no solo con los l\u00EDderes empatados. Las subastas de cofres y las subastas sin ofertas no terminan este desempate. Se abren los nuevos cofres antes de comparar otra vez los saldos y se repite si hace falta. Si no queda ning\u00FAn jugador, la partida termina en empate.",
              "Fuera de la subasta, S anuncia los saldos y los cofres sin abrir de todos los jugadores, tambi\u00E9n mientras se muestra una pregunta. Durante las pujas, usa May\u00FAs+S."),
            rule_section(:settings, "Ajustes de la mesa",
              "Antes de empezar, elige el idioma de las preguntas y selecciona dos o tres conjuntos de Quiz en los ajustes de la mesa. Marca los conjuntos con Espacio y confirma la selecci\u00F3n con Intro. Sus preguntas y categor\u00EDas se combinan para esta partida. Si el idioma elegido solo tiene un conjunto disponible, se usa ese; actualmente ocurre con el ingl\u00E9s y el ruso. Las preguntas pueden estar en un idioma distinto al de la interfaz.",
              "En lugar de los 10000 puntos iniciales puedes elegir cualquier n\u00FAmero entero entre 10 y 1000000. La aportaci\u00F3n al empezar cada subasta puede ir de 1 punto hasta todo el saldo inicial. La penalizaci\u00F3n tras tres subastas seguidas sin hacer ninguna oferta puede ser de 0 a 1000000. El cero anula la deducci\u00F3n, pero pasar sigue retir\u00E1ndote de esa subasta.",
              "Puedes elegir de 8 a 32 preguntas y de 1 a 5 segundos entre avisos. Por defecto son ocho preguntas y tres segundos. Sin apostar todo, la subasta cierra tras cuatro intervalos sin subida, dejando uno tras el tercer aviso. La probabilidad de cofre puede fijarse entre el 5 % y el 15 %, con un 10 % por defecto."),
            rule_section(:controls, "Controles",
              "Intro en el campo del importe: enviar la oferta escrita.",
              "A: escribe A en el campo del importe y pulsa Intro. Si tu total supera la mayor oferta, vas con todo y ganas la subasta al instante.",
              "Tab: ir a Retirarse de esta subasta.",
              "Abajo desde la pregunta: ir a las respuestas. Las flechas eligen una opci\u00F3n e Intro la env\u00EDa si ganaste la subasta.",
              "Intro en Abrir un cofre negro: abrir uno de tus cofres.",
              "S: fuera de las pujas, leer saldos y cofres cerrados.",
              "May\u00FAs+S: durante las pujas, leer saldos y cofres cerrados.",
              "P: consultar el bote.",
              "T: consultar qui\u00E9n puede actuar.",
              "H: consultar qui\u00E9n puja y qui\u00E9n ha pasado.",
              "D: consultar tus puntos.",
              "May\u00FAs+D: consultar los puntos de los dem\u00E1s jugadores.")
          ]
        when "pl"
          [
            rule_section(:aim, "Na czym polega gra",
              "Awantura o kas\u0119 \u0142\u0105czy wsp\u00F3ln\u0105 licytacj\u0119 z quizem dla dw\u00F3ch do o\u015Bmiu graczy, tak\u017Ce bot\u00F3w. Ka\u017Cde pytanie ma cztery odpowiedzi i jedn\u0105 poprawn\u0105. Domy\u015Blnie zaczynacie z 10000 punkt\u00F3w. Wygrywa osoba z najwi\u0119ksz\u0105 liczb\u0105 punkt\u00F3w spo\u015Br\u00F3d pozostaj\u0105cych w meczu. Czarne skrzynki zawieraj\u0105 osobne nagrody i nie zmieniaj\u0105 zwyci\u0119zcy.",
              "Ka\u017Cd\u0105 licytacj\u0119 rozpoczyna losowanie kategorii i wsp\u00F3lna wp\u0142ata do puli. Nast\u0119pnie licytujecie prawo do odpowiedzi na pytanie. Dobra odpowied\u017A daje ca\u0142\u0105 pul\u0119, a po b\u0142\u0119dnej pula zostaje na kolejn\u0105 licytacj\u0119."),
            rule_section(:rounds, "Pocz\u0105tek licytacji",
              "Ko\u0142o og\u0142asza kategori\u0119 pytania. Ka\u017Cdy gracz pozostaj\u0105cy w meczu wp\u0142aca wtedy 10 punkt\u00F3w do wsp\u00F3lnej puli. Kto nie ma na t\u0119 wp\u0142at\u0119, odpada na sta\u0142e. Punkty zgromadzone wcze\u015Bniej w puli pozostaj\u0105 w niej.",
              "Licytujecie r\u00F3wnocze\u015Bnie, bez czekania na swoj\u0105 kolej. Na pocz\u0105tku licytacji jeste\u015B w polu kwoty. Wpisz ofert\u0119 i zatwierd\u017A j\u0105 Enterem. Przyj\u0119ta oferta czy\u015Bci pole; po b\u0142\u0119dnej wpis zostaje, aby mo\u017Cna go by\u0142o poprawi\u0107. S\u0142yszysz numer rundy, pul\u0119, najwy\u017Csz\u0105 ofert\u0119 i osob\u0119 prowadz\u0105c\u0105.",
              "Po ofercie prowadz\u0105cy odlicza: po raz pierwszy, drugi i trzeci, domy\u015Blnie co trzy sekundy. Po trzeciej zapowiedzi licytacja pozostaje otwarta jeszcze przez jeden taki odst\u0119p. Ko\u0144czy j\u0105 dopiero og\u0142oszenie zwyci\u0119zcy. Ka\u017Cde podbicie rozpoczyna odliczanie od nowa. Przy domy\u015Blnych ustawieniach licytacja zamyka si\u0119 po dwunastu sekundach bez nowej oferty. Je\u015Bli nikt nie zalicytuje, pula przechodzi dalej.",
              "P odczytuje pul\u0119. T informuje, kto mo\u017Ce dzia\u0142a\u0107; podczas licytacji wszyscy uprawnieni gracze mog\u0105 sk\u0142ada\u0107 oferty r\u00F3wnocze\u015Bnie. H odczytuje, kto licytuje, a kto spasowa\u0142. D odczytuje twoje punkty, a Shift+D punkty pozosta\u0142ych graczy."),
            rule_section(:bidding, "Ile kosztuje oferta",
              "Oferta oznacza \u0142\u0105czn\u0105 kwot\u0119, kt\u00F3r\u0105 przeznaczasz na t\u0119 licytacj\u0119, poza wp\u0142at\u0105 na pocz\u0105tku. Ka\u017Cda oferta, tak\u017Ce vabank, musi by\u0107 wy\u017Csza od dotychczasowej najwy\u017Cszej oferty. Ka\u017Cdy licytuj\u0105cy p\u0142aci od razu. Punkty nie wracaj\u0105, nawet je\u015Bli p\u00F3\u017Aniej przegrasz licytacj\u0119 albo spasujesz.",
              "Przy podnoszeniu w\u0142asnej oferty dop\u0142acasz tylko r\u00F3\u017Cnic\u0119. Je\u015Bli zaoferowa\u0142e\u015B 100, podniesienie do 250 kosztuje jeszcze 150. Najwy\u017Cej mo\u017Cesz przeznaczy\u0107 pozosta\u0142e punkty oraz to, co ju\u017C wp\u0142aci\u0142e\u015B w ofertach w tej licytacji.",
              "Gdy masz jeszcze punkty, mo\u017Cesz zagra\u0107 vabank: wpisz A w polu kwoty i naci\u015Bnij Enter. Przeznaczasz wszystkie pozosta\u0142e punkty, a wcze\u015Bniejsze wp\u0142aty za oferty w tej licytacji doliczaj\u0105 si\u0119 do \u0142\u0105cznej kwoty. Mo\u017Cesz wpisa\u0107 t\u0119 \u0142\u0105czn\u0105 kwot\u0119 zamiast A. Je\u015Bli przebija ona najwy\u017Csz\u0105 ofert\u0119, vabank natychmiast ko\u0144czy licytacj\u0119 i daje ci pytanie albo czarn\u0105 skrzyni\u0119. Nikt nie mo\u017Ce ju\u017C podbi\u0107 stawki. Gdy twoja dost\u0119pna \u0142\u0105czna kwota nie przewy\u017Csza prowadz\u0105cej oferty, nie mo\u017Cesz zalicytowa\u0107 ani zagra\u0107 vabank.",
              "Prowadz\u0105cy nie mo\u017Ce si\u0119 wycofa\u0107: jego oferta jest wi\u0105\u017C\u0105ca. Mo\u017Ce jednak podbi\u0107 j\u0105 przed zamkni\u0119ciem. Wygrywa ostatnia zaliczona najwy\u017Csza oferta. Oferta, kt\u00F3ra dotrze do gry po terminie, zostaje odrzucona, nawet je\u015Bli odczyt komunikatu ko\u0144cz\u0105cego licytacj\u0119 jeszcze trwa."),
            rule_section(:passing, "Pasowanie i kara za brak ofert",
              "Je\u015Bli nie prowadzisz, przejd\u017A Tabem do przycisku Wycofaj si\u0119 z tej licytacji i naci\u015Bnij Enter. Nie musisz z niego korzysta\u0107. Wycofanie blokuje twoje dalsze oferty tylko w tej licytacji i nie ko\u0144czy jej wcze\u015Bniej. W nast\u0119pnej mo\u017Cesz zn\u00F3w licytowa\u0107. Wcze\u015Bniejsze wp\u0142aty zostaj\u0105 w puli.",
              "Licytacja bez \u017Cadnej twojej oferty zwi\u0119ksza licznik kolejnych licytacji bez udzia\u0142u, niezale\u017Cnie od tego, czy wybierzesz Pas, czy po prostu nic nie zalicytujesz. Pocz\u0105tkowa wp\u0142ata do puli nie jest ofert\u0105. Po trzech takich licytacjach z rz\u0119du, przy zamkni\u0119ciu trzeciej, p\u0142acisz 200 punkt\u00F3w do puli, a licznik wraca do zera. Je\u015Bli zosta\u0142o ci mniej ni\u017C 200 punkt\u00F3w, p\u0142acisz tylko pozosta\u0142\u0105 kwot\u0119. Ka\u017Cda przyj\u0119ta oferta zeruje licznik, nawet je\u015Bli p\u00F3\u017Aniej przegrasz t\u0119 licytacj\u0119 albo spasujesz."),
            rule_section(:question, "Odpowied\u017A na pytanie",
              "Po licytacji wszyscy mog\u0105 przeczyta\u0107 pytanie i odpowiedzi A\u2013D, ale odpowiedzie\u0107 mo\u017Ce tylko zwyci\u0119zca licytacji. Pytanie jest polem tekstowym do odczytu. Strza\u0142k\u0105 w d\u00F3\u0142 przejd\u017A do listy odpowiedzi, wybierz strza\u0142kami i zatwierd\u017A Enterem. Nie ma limitu czasu na odpowied\u017A.",
              "Za poprawn\u0105 odpowied\u017A zwyci\u0119zca licytacji otrzymuje ca\u0142\u0105 pul\u0119, a nowa pula zaczyna si\u0119 od zera. Po b\u0142\u0119dnej odpowiedzi wszystko zostaje na nast\u0119pn\u0105 licytacj\u0119. Je\u015Bli zagra\u0142e\u015B za wszystko i po b\u0142\u0119dnej odpowiedzi nie masz ju\u017C punkt\u00F3w, odpadasz na sta\u0142e.",
              "Przed odpowiedzi\u0105 zwyci\u0119zca licytacji mo\u017Ce raz kupi\u0107 podpowied\u017A usuwaj\u0105c\u0105 dwie b\u0142\u0119dne odpowiedzi. Kosztuje ona 10% pozosta\u0142ych mu punkt\u00F3w, w zaokr\u0105gleniu w g\u00F3r\u0119, ale co najmniej punkt. Przycisk podaje dok\u0142adn\u0105 cen\u0119. Zap\u0142ata znika z gry, zamiast trafia\u0107 do puli. Bez punkt\u00F3w nie mo\u017Cna kupi\u0107 podpowiedzi."),
            rule_section(:chests, "Czarne skrzynie",
              "Domy\u015Blnie przy 10% losowa\u0144 czarna skrzynka zast\u0119puje kategori\u0119 i pytanie. Licytujcie j\u0105 jak zwykle. Zwyci\u0119zca zatrzymuje zamkni\u0119t\u0105 skrzynk\u0119, a pula przechodzi dalej. Licytacje skrzynek nie wliczaj\u0105 si\u0119 do limitu pyta\u0144.",
              "Na ko\u0144cu ka\u017Cdy otwiera swoje skrzynki, r\u00F3wnie\u017C osoby wyeliminowane. Dla ka\u017Cdej wybierz Otw\u00F3rz czarn\u0105 skrzynk\u0119. W \u015Brodku jest dodatkowa nagroda: 100, 500, 1000, 2500, 5000, 7500 albo 10000, z r\u00F3wnymi szansami. Te nagrody nie zmieniaj\u0105 punkt\u00F3w, odpadni\u0119cia ani zwyci\u0119zcy meczu. Nie ma w nich strat ani bankruta."),
            rule_section(:finish, "Koniec meczu",
              "Zwyk\u0142y mecz obejmuje osiem pyta\u0144 z udzielon\u0105 odpowiedzi\u0105, dobr\u0105 albo z\u0142\u0105. Skrzynki i licytacje bez ofert si\u0119 nie licz\u0105. Mecz ko\u0144czy si\u0119 te\u017C, gdy pozostanie najwy\u017Cej jedna osoba. Przed og\u0142oszeniem wyniku wszyscy otwieraj\u0105 skrzynki, ale ich nagrody nie zmieniaj\u0105 kolejno\u015Bci graczy.",
              "Po otwarciu wszystkich skrzy\u0144 wygrywa gracz z najwi\u0119ksz\u0105 liczb\u0105 punkt\u00F3w spo\u015Br\u00F3d os\u00F3b nadal w meczu. Je\u015Bli kilka z nich ma r\u00F3wny najwy\u017Cszy wynik, gracie do odpowiedzi na kolejne pytanie z udzia\u0142em wszystkich pozostaj\u0105cych graczy, nie tylko lider\u00F3w. Licytacje skrzy\u0144 i licytacje bez ofert nie ko\u0144cz\u0105 tej dogrywki. Przed kolejnym por\u00F3wnaniem otwieracie nowe skrzynie; w razie potrzeby powtarzacie dogrywk\u0119. Gdy nikt nie pozostaje w grze, mecz ko\u0144czy si\u0119 remisem.",
              "S odczytuje salda wszystkich graczy i liczb\u0119 ich zamkni\u0119tych skrzy\u0144 poza licytacj\u0105, tak\u017Ce podczas pytania. W trakcie licytacji u\u017Cyj Shift+S."),
            rule_section(:settings, "Ustawienia sto\u0142u",
              "Przed rozpocz\u0119ciem wybierz w ustawieniach sto\u0142u j\u0119zyk pyta\u0144 oraz dwa lub trzy zestawy Quizu. Spacj\u0105 zaznacz potrzebne zestawy, a Enterem zatwierd\u017A wyb\u00F3r. Ich pytania i kategorie zostan\u0105 po\u0142\u0105czone na ten mecz. Je\u015Bli dla wybranego j\u0119zyka jest dost\u0119pny tylko jeden zestaw, korzystasz z niego; obecnie tak jest dla angielskiego i rosyjskiego. J\u0119zyk pyta\u0144 mo\u017Ce by\u0107 inny ni\u017C j\u0119zyk interfejsu.",
              "Zamiast 10000 punkt\u00F3w pocz\u0105tkowych mo\u017Cesz ustawi\u0107 dowoln\u0105 liczb\u0119 ca\u0142kowit\u0105 od 10 do 1000000. Wp\u0142ata na pocz\u0105tku licytacji mo\u017Ce wynosi\u0107 od 1 punktu do ca\u0142ego pocz\u0105tkowego salda. Kara po trzech kolejnych licytacjach bez w\u0142asnej oferty mo\u017Ce wynosi\u0107 od 0 do 1000000. Zero wy\u0142\u0105cza odejmowanie punkt\u00F3w, ale pas nadal wycofuje z bie\u017C\u0105cej licytacji.",
              "Mo\u017Cesz wybra\u0107 od 8 do 32 pyta\u0144 i od 1 do 5 sekund mi\u0119dzy zapowiedziami. Domy\u015Blnie jest osiem pyta\u0144 i trzy sekundy. Bez va banque licytacja zamyka si\u0119 po czterech odst\u0119pach bez podbicia, zostawiaj\u0105c jeden odst\u0119p po trzeciej zapowiedzi. Szans\u0119 na czarn\u0105 skrzynk\u0119 ustawisz od 5% do 15%, domy\u015Blnie 10%."),
            rule_section(:controls, "Sterowanie",
              "Enter w polu kwoty: wy\u015Blij wpisan\u0105 ofert\u0119.",
              "A: wpisz A w polu kwoty i zatwierd\u017A Enterem. Vabank natychmiast wygrywa licytacj\u0119, je\u015Bli twoja \u0142\u0105czna kwota przebija najwy\u017Csz\u0105 ofert\u0119.",
              "Tab: przejd\u017A do przycisku Wycofaj si\u0119 z tej licytacji.",
              "Strza\u0142ka w d\u00F3\u0142 z pytania: przejd\u017A do odpowiedzi. Strza\u0142ki wybieraj\u0105, a Enter zatwierdza, je\u015Bli wygra\u0142e\u015B licytacj\u0119.",
              "Enter na Otw\u00F3rz czarn\u0105 skrzyni\u0119: otw\u00F3rz jedn\u0105 ze swoich skrzy\u0144.",
              "S: poza licytacj\u0105 odczytaj punkty i zamkni\u0119te skrzynki.",
              "Shift+S: podczas licytacji odczytaj punkty i zamkni\u0119te skrzynki.",
              "P: odczytaj pul\u0119.",
              "T: odczytaj, kto mo\u017Ce dzia\u0142a\u0107.",
              "H: odczytaj, kto licytuje, a kto spasowa\u0142.",
              "D: odczytaj w\u0142asne punkty.",
              "Shift+D: odczytaj punkty pozosta\u0142ych graczy.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0414\u0435\u043D\u0435\u0436\u043D\u044B\u0439 \u0430\u0443\u043A\u0446\u0438\u043E\u043D \u0441\u043E\u0447\u0435\u0442\u0430\u0435\u0442 \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u0442\u043E\u0440\u0433\u0438 \u0438 \u0432\u0438\u043A\u0442\u043E\u0440\u0438\u043D\u0443 \u0434\u043B\u044F \u0434\u0432\u0443\u0445\u2013\u0432\u043E\u0441\u044C\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u043E\u0432, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0431\u043E\u0442\u043E\u0432. \u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u0430 \u0447\u0435\u0442\u044B\u0440\u0435 \u043E\u0442\u0432\u0435\u0442\u0430 \u0438 \u043E\u0434\u0438\u043D \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u0441\u0435 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u0441 10000 \u043E\u0447\u043A\u043E\u0432. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0432 \u0438\u0433\u0440\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0441 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u043C \u0441\u0447\u0451\u0442\u043E\u043C. \u0427\u0451\u0440\u043D\u044B\u0435 \u044F\u0449\u0438\u043A\u0438 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0442 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0440\u0438\u0437\u044B \u0438 \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F.",
              "\u041A\u0430\u0436\u0434\u044B\u0435 \u0442\u043E\u0440\u0433\u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442\u0441\u044F \u0441 \u0432\u044B\u0431\u043E\u0440\u0430 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438 \u0438 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u0437\u043D\u043E\u0441\u0430 \u0432\u0441\u0435\u0445 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u0417\u0430\u0442\u0435\u043C \u0432\u044B \u0442\u043E\u0440\u0433\u0443\u0435\u0442\u0435\u0441\u044C \u0437\u0430 \u043F\u0440\u0430\u0432\u043E \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u043D\u0430 \u0432\u043E\u043F\u0440\u043E\u0441. \u0412\u0435\u0440\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u0432\u0435\u0441\u044C \u0431\u0430\u043D\u043A, \u0430 \u043F\u043E\u0441\u043B\u0435 \u043E\u0448\u0438\u0431\u043A\u0438 \u0431\u0430\u043D\u043A \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0442\u043E\u0440\u0433\u0438."),
            rule_section(:rounds, "\u041D\u0430\u0447\u0430\u043B\u043E \u0442\u043E\u0440\u0433\u043E\u0432",
              "\u041A\u043E\u043B\u0435\u0441\u043E \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044E \u0432\u043E\u043F\u0440\u043E\u0441\u0430. \u041A\u0430\u0436\u0434\u044B\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0432\u043D\u043E\u0441\u0438\u0442 \u0432 \u043E\u0431\u0449\u0438\u0439 \u0431\u0430\u043D\u043A 10 \u043E\u0447\u043A\u043E\u0432. \u0415\u0441\u043B\u0438 \u043D\u0430 \u0432\u0437\u043D\u043E\u0441 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043E\u0447\u043A\u043E\u0432, \u0438\u0433\u0440\u043E\u043A \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442 \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0420\u0430\u043D\u0435\u0435 \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u043D\u044B\u0435 \u0432 \u0431\u0430\u043D\u043A\u0435 \u043E\u0447\u043A\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432 \u043D\u0451\u043C.",
              "\u0421\u0442\u0430\u0432\u043A\u0438 \u0434\u0435\u043B\u0430\u044E\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E, \u0436\u0434\u0430\u0442\u044C \u0441\u0432\u043E\u0435\u0439 \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043D\u0435 \u043D\u0443\u0436\u043D\u043E. \u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0442\u043E\u0440\u0433\u043E\u0432 \u0444\u043E\u043A\u0443\u0441 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u043F\u043E\u043B\u0435 \u0441\u0443\u043C\u043C\u044B. \u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u043D\u044F\u0442\u043E\u0439 \u0441\u0442\u0430\u0432\u043A\u0438 \u043F\u043E\u043B\u0435 \u043E\u0447\u0438\u0449\u0430\u0435\u0442\u0441\u044F; \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u0442\u0435\u043A\u0441\u0442 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0434\u043B\u044F \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F. \u041E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0440\u0430\u0443\u043D\u0434 \u0441 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u043C, \u0431\u0430\u043D\u043A, \u0441\u0430\u043C\u0430\u044F \u0432\u044B\u0441\u043E\u043A\u0430\u044F \u0441\u0442\u0430\u0432\u043A\u0430 \u0438 \u0438\u043C\u044F \u043B\u0438\u0434\u0435\u0440\u0430 \u0442\u043E\u0440\u0433\u043E\u0432.",
              "\u041F\u043E\u0441\u043B\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u0432\u0435\u0434\u0443\u0449\u0438\u0439 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439, \u0432\u0442\u043E\u0440\u043E\u0439 \u0438 \u0442\u0440\u0435\u0442\u0438\u0439 \u0440\u0430\u0437, \u043E\u0431\u044B\u0447\u043D\u043E \u0441 \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B\u043E\u043C \u0442\u0440\u0438 \u0441\u0435\u043A\u0443\u043D\u0434\u044B. \u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0442\u043E\u0440\u0433\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B \u0435\u0449\u0451 \u043E\u0434\u0438\u043D \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B; \u0438\u0445 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F. \u041F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043E\u0442\u0441\u0447\u0451\u0442 \u0437\u0430\u043D\u043E\u0432\u043E. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0442\u043E\u0440\u0433\u0438 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0447\u0435\u0440\u0435\u0437 \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0435\u043A\u0443\u043D\u0434 \u0431\u0435\u0437 \u043D\u043E\u0432\u043E\u0439 \u0437\u0430\u044F\u0432\u043A\u0438. \u0415\u0441\u043B\u0438 \u0437\u0430\u044F\u0432\u043E\u043A \u043D\u0435\u0442, \u0431\u0430\u043D\u043A \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u0434\u0430\u043B\u044C\u0448\u0435.",
              "P \u0447\u0438\u0442\u0430\u0435\u0442 \u0431\u0430\u043D\u043A. T \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442, \u043A\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C; \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0442\u043E\u0440\u0433\u043E\u0432 \u0432\u0441\u0435 \u0434\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u044B\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u043C\u043E\u0433\u0443\u0442 \u0434\u0435\u043B\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0438 \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E. H \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442, \u043A\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u0442 \u0441\u0442\u0430\u0432\u043A\u0438, \u0430 \u043A\u0442\u043E \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u043B. D \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u0430\u0448\u0438 \u043E\u0447\u043A\u0438, \u0430 Shift+D \u2014 \u043E\u0447\u043A\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432."),
            rule_section(:bidding, "\u0421\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0442\u043E\u0438\u0442 \u0441\u0442\u0430\u0432\u043A\u0430",
              "\u0421\u0442\u0430\u0432\u043A\u0430 \u2014 \u044D\u0442\u043E \u043E\u0431\u0449\u0430\u044F \u0441\u0443\u043C\u043C\u0430, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0432\u044B \u043E\u0442\u0434\u0430\u0451\u0442\u0435 \u0432 \u044D\u0442\u0438\u0445 \u0442\u043E\u0440\u0433\u0430\u0445 \u0441\u0432\u0435\u0440\u0445 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u0437\u043D\u043E\u0441\u0430. \u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0442\u0430\u0432\u043A\u0430, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0432\u0430-\u0431\u0430\u043D\u043A, \u0434\u043E\u043B\u0436\u043D\u0430 \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0430\u043C\u0443\u044E \u0432\u044B\u0441\u043E\u043A\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443. \u041A\u0430\u0436\u0434\u044B\u0439 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0442\u043E\u0440\u0433\u043E\u0432 \u043F\u043B\u0430\u0442\u0438\u0442 \u0441\u0440\u0430\u0437\u0443. \u041E\u0447\u043A\u0438 \u043D\u0435 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u043F\u043E\u0437\u0434\u043D\u0435\u0435 \u0432\u044B \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0435\u0442\u0435 \u0442\u043E\u0440\u0433\u0438 \u0438\u043B\u0438 \u0441\u043F\u0430\u0441\u0443\u0435\u0442\u0435.",
              "\u041F\u0440\u0438 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0438 \u0441\u0432\u043E\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0438 \u0432\u044B \u0434\u043E\u043F\u043B\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0440\u0430\u0437\u043D\u0438\u0446\u0443. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0441\u043B\u0435 \u0441\u0442\u0430\u0432\u043A\u0438 100 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0434\u043E 250 \u0441\u0442\u043E\u0438\u0442 \u0435\u0449\u0451 150. \u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u0430\u044F \u0441\u0442\u0430\u0432\u043A\u0430 \u0440\u0430\u0432\u043D\u0430 \u043E\u0441\u0442\u0430\u0432\u0448\u0435\u043C\u0443\u0441\u044F \u0431\u0430\u043B\u0430\u043D\u0441\u0443 \u043F\u043B\u044E\u0441 \u043E\u0447\u043A\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0432\u044B \u0443\u0436\u0435 \u0432\u043D\u0435\u0441\u043B\u0438 \u0441\u0442\u0430\u0432\u043A\u0430\u043C\u0438 \u0432 \u044D\u0442\u0438\u0445 \u0442\u043E\u0440\u0433\u0430\u0445.",
              "\u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0449\u0451 \u043E\u0441\u0442\u0430\u043B\u0438\u0441\u044C \u043E\u0447\u043A\u0438, \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u0439\u0442\u0438 \u0432\u0430-\u0431\u0430\u043D\u043A: \u0432\u0432\u0435\u0434\u0438\u0442\u0435 A \u0432 \u043F\u043E\u043B\u0435 \u0441\u0443\u043C\u043C\u044B \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0412\u044B \u043E\u0442\u0434\u0430\u0451\u0442\u0435 \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043E\u0447\u043A\u0438; \u043A \u043E\u0431\u0449\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0438 \u043E\u0447\u043A\u0438, \u0443\u0436\u0435 \u0432\u043D\u0435\u0441\u0451\u043D\u043D\u044B\u0435 \u0432\u0430\u043C\u0438 \u0432 \u044D\u0442\u0438\u0445 \u0442\u043E\u0440\u0433\u0430\u0445. \u0412\u043C\u0435\u0441\u0442\u043E A \u043C\u043E\u0436\u043D\u043E \u0432\u0432\u0435\u0441\u0442\u0438 \u044D\u0442\u0443 \u043E\u0431\u0449\u0443\u044E \u0441\u0443\u043C\u043C\u0443. \u0415\u0441\u043B\u0438 \u043E\u043D\u0430 \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0435\u0442 \u0441\u0430\u043C\u0443\u044E \u0432\u044B\u0441\u043E\u043A\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443, \u0442\u043E\u0440\u0433\u0438 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u0432\u043E\u043F\u0440\u043E\u0441 \u0438\u043B\u0438 \u0447\u0451\u0440\u043D\u044B\u0439 \u0441\u0443\u043D\u0434\u0443\u043A. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0443 \u0443\u0436\u0435 \u043D\u0435\u043B\u044C\u0437\u044F. \u0415\u0441\u043B\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430\u044F \u0432\u0430\u043C \u043E\u0431\u0449\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u043D\u0435 \u0432\u044B\u0448\u0435 \u0441\u0442\u0430\u0432\u043A\u0438 \u043B\u0438\u0434\u0435\u0440\u0430, \u0432\u044B \u043D\u0435 \u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0443 \u0438\u043B\u0438 \u043F\u043E\u0439\u0442\u0438 \u0432\u0430-\u0431\u0430\u043D\u043A.",
              "\u041B\u0438\u0434\u0438\u0440\u0443\u044E\u0449\u0438\u0439 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u043E\u0442 \u0437\u0430\u044F\u0432\u043A\u0438, \u043D\u043E \u0434\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C \u0435\u0451. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043F\u0440\u0438\u043D\u044F\u0442\u0430\u044F \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u0437\u0430\u044F\u0432\u043A\u0430. \u0417\u0430\u044F\u0432\u043A\u0430, \u043F\u043E\u0441\u0442\u0443\u043F\u0438\u0432\u0448\u0430\u044F \u043F\u043E\u0441\u043B\u0435 \u0441\u0440\u043E\u043A\u0430, \u043E\u0442\u043A\u043B\u043E\u043D\u044F\u0435\u0442\u0441\u044F, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0438 \u0435\u0449\u0451 \u0437\u0432\u0443\u0447\u0438\u0442."),
            rule_section(:passing, "\u041F\u0430\u0441 \u0438 \u0448\u0442\u0440\u0430\u0444 \u0437\u0430 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0441\u0442\u0430\u0432\u043E\u043A",
              "\u0415\u0441\u043B\u0438 \u0432\u044B \u043D\u0435 \u043B\u0438\u0434\u0438\u0440\u0443\u0435\u0442\u0435, \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u043A \u043E\u0442\u043A\u0430\u0437\u0443 \u043E\u0442 \u044D\u0442\u043E\u0439 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u042D\u0442\u043E \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E: \u043E\u0442\u043A\u0430\u0437 \u0431\u043B\u043E\u043A\u0438\u0440\u0443\u0435\u0442 \u0432\u0430\u0448\u0438 \u0434\u0430\u043B\u044C\u043D\u0435\u0439\u0448\u0438\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u0442\u0435\u043A\u0443\u0449\u0438\u0445 \u0442\u043E\u0440\u0433\u0430\u0445 \u0438 \u043D\u0435 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0438\u0445 \u0440\u0430\u043D\u044C\u0448\u0435. \u0412 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0442\u043E\u0440\u0433\u0430\u0445 \u0441\u043D\u043E\u0432\u0430 \u043C\u043E\u0436\u043D\u043E \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C. \u041F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0435 \u0432\u0437\u043D\u043E\u0441\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432 \u0431\u0430\u043D\u043A\u0435.",
              "\u0422\u043E\u0440\u0433\u0438, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0432\u044B \u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u043B\u0438 \u043D\u0438 \u043E\u0434\u043D\u043E\u0439 \u0441\u0442\u0430\u0432\u043A\u0438, \u0437\u0430\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0441\u0435\u0440\u0438\u044E \u0442\u043E\u0440\u0433\u043E\u0432 \u0431\u0435\u0437 \u0443\u0447\u0430\u0441\u0442\u0438\u044F. \u041D\u0435\u0432\u0430\u0436\u043D\u043E, \u043D\u0430\u0436\u0430\u043B\u0438 \u043B\u0438 \u0432\u044B \u00AB\u041F\u0430\u0441\u00BB \u0438\u043B\u0438 \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435 \u0441\u0442\u0430\u043B\u0438 \u0434\u0435\u043B\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0443. \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u0437\u043D\u043E\u0441 \u0441\u0442\u0430\u0432\u043A\u043E\u0439 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435 \u0442\u0440\u0451\u0445 \u0442\u0430\u043A\u0438\u0445 \u0442\u043E\u0440\u0433\u043E\u0432 \u043F\u043E\u0434\u0440\u044F\u0434 \u043F\u0440\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0438 \u0442\u0440\u0435\u0442\u044C\u0438\u0445 \u0432\u044B \u043F\u043B\u0430\u0442\u0438\u0442\u0435 \u0432 \u0431\u0430\u043D\u043A 200 \u043E\u0447\u043A\u043E\u0432, \u0430 \u0441\u0447\u0451\u0442\u0447\u0438\u043A \u043E\u0431\u043D\u0443\u043B\u044F\u0435\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043C\u0435\u043D\u044C\u0448\u0435 200 \u043E\u0447\u043A\u043E\u0432, \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0441\u0442\u0430\u0432\u0448\u0430\u044F\u0441\u044F \u0441\u0443\u043C\u043C\u0430. \u041B\u044E\u0431\u0430\u044F \u043F\u0440\u0438\u043D\u044F\u0442\u0430\u044F \u0441\u0442\u0430\u0432\u043A\u0430 \u043E\u0431\u043D\u0443\u043B\u044F\u0435\u0442 \u0441\u0447\u0451\u0442\u0447\u0438\u043A, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0437\u0430\u0442\u0435\u043C \u0432\u044B \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u0435\u0442\u0435 \u0442\u043E\u0440\u0433\u0438 \u0438\u043B\u0438 \u0441\u043F\u0430\u0441\u0443\u0435\u0442\u0435."),
            rule_section(:question, "\u041E\u0442\u0432\u0435\u0442 \u043D\u0430 \u0432\u043E\u043F\u0440\u043E\u0441",
              "\u041F\u043E\u0441\u043B\u0435 \u0442\u043E\u0440\u0433\u043E\u0432 \u0432\u0441\u0435 \u043C\u043E\u0433\u0443\u0442 \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0432\u043E\u043F\u0440\u043E\u0441 \u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B A\u2013D, \u043D\u043E \u043E\u0442\u0432\u0435\u0442\u0438\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432. \u0412\u043E\u043F\u0440\u043E\u0441 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0442\u0435\u043A\u0441\u0442\u043E\u0432\u043E\u043C \u043F\u043E\u043B\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0434\u043B\u044F \u0447\u0442\u0435\u043D\u0438\u044F. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0443 \u0432\u043D\u0438\u0437, \u0447\u0442\u043E\u0431\u044B \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u043F\u0438\u0441\u043A\u0443 \u043E\u0442\u0432\u0435\u0442\u043E\u0432, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0412\u0440\u0435\u043C\u044F \u043D\u0430 \u043E\u0442\u0432\u0435\u0442 \u043D\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043E.",
              "\u0417\u0430 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0432\u0435\u0441\u044C \u0431\u0430\u043D\u043A, \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0433\u043E \u043D\u043E\u0432\u044B\u0439 \u0431\u0430\u043D\u043A \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u044F. \u041F\u043E\u0441\u043B\u0435 \u043E\u0448\u0438\u0431\u043A\u0438 \u0432\u0435\u0441\u044C \u0431\u0430\u043D\u043A \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0442\u043E\u0440\u0433\u0438. \u0415\u0441\u043B\u0438 \u0432\u044B \u043F\u043E\u0448\u043B\u0438 \u0432\u0430-\u0431\u0430\u043D\u043A \u0438 \u043F\u043E\u0441\u043B\u0435 \u043D\u0435\u0432\u0435\u0440\u043D\u043E\u0433\u043E \u043E\u0442\u0432\u0435\u0442\u0430 \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C, \u0432\u044B \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u043E.",
              "\u041F\u0435\u0440\u0435\u0434 \u043E\u0442\u0432\u0435\u0442\u043E\u043C \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u043C\u043E\u0436\u0435\u0442 \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u043A\u0443\u043F\u0438\u0442\u044C \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0443, \u0443\u0431\u0438\u0440\u0430\u044E\u0449\u0443\u044E \u0434\u0432\u0430 \u043D\u0435\u0432\u0435\u0440\u043D\u044B\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430. \u0426\u0435\u043D\u0430 \u2014 10 % \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u043E\u0447\u043A\u043E\u0432 \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0432\u0432\u0435\u0440\u0445, \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u043E\u0434\u043D\u043E \u043E\u0447\u043A\u043E; \u043A\u043D\u043E\u043F\u043A\u0430 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0442\u043E\u0447\u043D\u0443\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C. \u041F\u043B\u0430\u0442\u0430 \u0443\u0445\u043E\u0434\u0438\u0442 \u0438\u0437 \u0438\u0433\u0440\u044B, \u0430 \u043D\u0435 \u0432 \u0431\u0430\u043D\u043A. \u0411\u0435\u0437 \u043E\u0447\u043A\u043E\u0432 \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0443 \u043A\u0443\u043F\u0438\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F."),
            rule_section(:chests, "\u0427\u0451\u0440\u043D\u044B\u0435 \u0441\u0443\u043D\u0434\u0443\u043A\u0438",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0447\u0451\u0440\u043D\u044B\u0439 \u044F\u0449\u0438\u043A \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044E \u0438 \u0432\u043E\u043F\u0440\u043E\u0441 \u0432 10 % \u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0439. \u0422\u043E\u0440\u0433\u0443\u0439\u0442\u0435\u0441\u044C \u0437\u0430 \u043D\u0435\u0433\u043E \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u043E. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0435\u0433\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u043C, \u0431\u0430\u043D\u043A \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u0434\u0430\u043B\u044C\u0448\u0435. \u0422\u043E\u0440\u0433\u0438 \u0437\u0430 \u044F\u0449\u0438\u043A\u0438 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u043B\u0438\u043C\u0438\u0442\u0435 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432.",
              "\u0412 \u043A\u043E\u043D\u0446\u0435 \u043A\u0430\u0436\u0434\u044B\u0439 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u0432\u043E\u0438 \u044F\u0449\u0438\u043A\u0438, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0432\u044B\u0431\u044B\u0432\u0448\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u0414\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 \u0447\u0451\u0440\u043D\u043E\u0433\u043E \u044F\u0449\u0438\u043A\u0430. \u0412 \u043D\u0451\u043C \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u0440\u0438\u0437: 100, 500, 1000, 2500, 5000, 7500 \u0438\u043B\u0438 10000, \u0441 \u0440\u0430\u0432\u043D\u044B\u043C\u0438 \u0448\u0430\u043D\u0441\u0430\u043C\u0438. \u041F\u0440\u0438\u0437\u044B \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442 \u043E\u0447\u043A\u0438, \u0432\u044B\u0431\u044B\u0432\u0430\u043D\u0438\u0435 \u0438\u043B\u0438 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u043C\u0430\u0442\u0447\u0430. \u0412 \u044F\u0449\u0438\u043A\u0430\u0445 \u043D\u0435\u0442 \u043F\u043E\u0442\u0435\u0440\u044C \u0438\u043B\u0438 \u0431\u0430\u043D\u043A\u0440\u043E\u0442\u0441\u0442\u0432\u0430."),
            rule_section(:finish, "\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043C\u0430\u0442\u0447\u0430",
              "\u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u043C\u0430\u0442\u0447 \u0434\u043B\u0438\u0442\u0441\u044F \u0432\u043E\u0441\u0435\u043C\u044C \u043E\u0442\u0432\u0435\u0447\u0435\u043D\u043D\u044B\u0445 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432, \u0432\u0435\u0440\u043D\u043E \u0438\u043B\u0438 \u043D\u0435\u0432\u0435\u0440\u043D\u043E. \u042F\u0449\u0438\u043A\u0438 \u0438 \u0442\u043E\u0440\u0433\u0438 \u0431\u0435\u0437 \u0437\u0430\u044F\u0432\u043E\u043A \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u041C\u0430\u0442\u0447 \u0442\u0430\u043A\u0436\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u0435\u0441\u043B\u0438 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430. \u0412\u0441\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u044F\u0449\u0438\u043A\u0438 \u043F\u0435\u0440\u0435\u0434 \u0438\u0442\u043E\u0433\u043E\u0432\u044B\u043C \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435\u043C, \u043D\u043E \u043F\u0440\u0438\u0437\u044B \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442 \u043C\u0435\u0441\u0442\u0430.",
              "\u041F\u043E\u0441\u043B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u044F \u0432\u0441\u0435\u0445 \u0441\u0443\u043D\u0434\u0443\u043A\u043E\u0432 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0432 \u0438\u0433\u0440\u0435 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0441 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u043C \u0431\u0430\u043B\u0430\u043D\u0441\u043E\u043C. \u0415\u0441\u043B\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0434\u0435\u043B\u044F\u0442 \u043F\u0435\u0440\u0432\u043E\u0435 \u043C\u0435\u0441\u0442\u043E, \u0438\u0433\u0440\u0430 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F \u0434\u043E \u043E\u0442\u0432\u0435\u0442\u0430 \u0435\u0449\u0451 \u043D\u0430 \u043E\u0434\u0438\u043D \u0432\u043E\u043F\u0440\u043E\u0441 \u0441\u043E \u0432\u0441\u0435\u043C\u0438, \u043A\u0442\u043E \u0435\u0449\u0451 \u0432 \u0438\u0433\u0440\u0435, \u0430 \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0441 \u043B\u0438\u0434\u0435\u0440\u0430\u043C\u0438. \u0422\u043E\u0440\u0433\u0438 \u0437\u0430 \u0441\u0443\u043D\u0434\u0443\u043A\u0438 \u0438 \u0442\u043E\u0440\u0433\u0438 \u0431\u0435\u0437 \u0441\u0442\u0430\u0432\u043E\u043A \u044D\u0442\u0443 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u0443\u044E \u0438\u0433\u0440\u0443 \u043D\u0435 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0442. \u041D\u043E\u0432\u044B\u0435 \u0441\u0443\u043D\u0434\u0443\u043A\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u0435\u0440\u0435\u0434 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C \u0441\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u0435\u043C \u0431\u0430\u043B\u0430\u043D\u0441\u043E\u0432; \u043F\u0440\u0438 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u0438 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0438\u0433\u0440\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u043D\u0435 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043D\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430, \u043C\u0430\u0442\u0447 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u043D\u0438\u0447\u044C\u044E.",
              "\u0412\u043D\u0435 \u0442\u043E\u0440\u0433\u043E\u0432 S \u0447\u0438\u0442\u0430\u0435\u0442 \u0431\u0430\u043B\u0430\u043D\u0441\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0438 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0438\u0445 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u0441\u0443\u043D\u0434\u0443\u043A\u043E\u0432, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u043E\u043F\u0440\u043E\u0441\u0430. \u0412\u043E \u0432\u0440\u0435\u043C\u044F \u0442\u043E\u0440\u0433\u043E\u0432 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 Shift+S."),
            rule_section(:settings, "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0441\u0442\u043E\u043B\u0430",
              "\u0414\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u0438\u0433\u0440\u044B \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u044F\u0437\u044B\u043A \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432 \u0438 \u0434\u0432\u0430 \u0438\u043B\u0438 \u0442\u0440\u0438 \u043D\u0430\u0431\u043E\u0440\u0430 \u00AB\u0412\u0438\u043A\u0442\u043E\u0440\u0438\u043D\u044B\u00BB. \u041E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 \u043D\u0443\u0436\u043D\u044B\u0435 \u043D\u0430\u0431\u043E\u0440\u044B \u043F\u0440\u043E\u0431\u0435\u043B\u043E\u043C \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0432\u044B\u0431\u043E\u0440 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter. \u0418\u0445 \u0432\u043E\u043F\u0440\u043E\u0441\u044B \u0438 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438 \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u044F\u044E\u0442\u0441\u044F \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u043C\u0430\u0442\u0447\u0430. \u0415\u0441\u043B\u0438 \u0434\u043B\u044F \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u044F\u0437\u044B\u043A\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u0438\u043D \u043D\u0430\u0431\u043E\u0440, \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043E\u043D; \u0441\u0435\u0439\u0447\u0430\u0441 \u044D\u0442\u043E \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u043C\u0443 \u0438 \u0440\u0443\u0441\u0441\u043A\u043E\u043C\u0443. \u042F\u0437\u044B\u043A \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043B\u0438\u0447\u0430\u0442\u044C\u0441\u044F \u043E\u0442 \u044F\u0437\u044B\u043A\u0430 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430.",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0445 10000 \u043E\u0447\u043A\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0434\u0430\u0442\u044C \u043B\u044E\u0431\u043E\u0435 \u0446\u0435\u043B\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043E\u0442 10 \u0434\u043E 1000000. \u0412\u0437\u043D\u043E\u0441 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0442\u043E\u0440\u0433\u043E\u0432 \u043C\u043E\u0436\u0435\u0442 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0442\u044C \u043E\u0442 1 \u043E\u0447\u043A\u0430 \u0434\u043E \u0432\u0441\u0435\u0433\u043E \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0431\u0430\u043B\u0430\u043D\u0441\u0430. \u0428\u0442\u0440\u0430\u0444 \u043F\u043E\u0441\u043B\u0435 \u0442\u0440\u0451\u0445 \u0442\u043E\u0440\u0433\u043E\u0432 \u043F\u043E\u0434\u0440\u044F\u0434 \u0431\u0435\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u0441\u0442\u0430\u0432\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043E\u0442 0 \u0434\u043E 1000000. \u041D\u043E\u043B\u044C \u043E\u0442\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0441\u043F\u0438\u0441\u0430\u043D\u0438\u0435, \u043D\u043E \u043F\u0430\u0441 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0432\u044B\u0432\u043E\u0434\u0438\u0442 \u0432\u0430\u0441 \u0438\u0437 \u0442\u0435\u043A\u0443\u0449\u0438\u0445 \u0442\u043E\u0440\u0433\u043E\u0432.",
              "\u041C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0442 8 \u0434\u043E 32 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432 \u0438 \u043E\u0442 1 \u0434\u043E 5 \u0441\u0435\u043A\u0443\u043D\u0434 \u043C\u0435\u0436\u0434\u0443 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F\u043C\u0438. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u2014 \u0432\u043E\u0441\u0435\u043C\u044C \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432 \u0438 \u0442\u0440\u0438 \u0441\u0435\u043A\u0443\u043D\u0434\u044B. \u0411\u0435\u0437 \u0432\u0430-\u0431\u0430\u043D\u043A\u0430 \u0442\u043E\u0440\u0433\u0438 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0447\u0435\u0440\u0435\u0437 \u0447\u0435\u0442\u044B\u0440\u0435 \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B\u0430 \u0431\u0435\u0437 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F, \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044F \u043E\u0434\u0438\u043D \u043F\u043E\u0441\u043B\u0435 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F. \u0428\u0430\u043D\u0441 \u0447\u0451\u0440\u043D\u043E\u0433\u043E \u044F\u0449\u0438\u043A\u0430 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0434\u0430\u0442\u044C \u043E\u0442 5 \u0434\u043E 15 %, \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E 10 %."),
            rule_section(:controls, "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435",
              "Enter \u0432 \u043F\u043E\u043B\u0435 \u0441\u0443\u043C\u043C\u044B: \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0432\u0432\u0435\u0434\u0451\u043D\u043D\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443.",
              "A: \u0432\u0432\u0435\u0434\u0438\u0442\u0435 A \u0432 \u043F\u043E\u043B\u0435 \u0441\u0443\u043C\u043C\u044B \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0415\u0441\u043B\u0438 \u043E\u0431\u0449\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0435\u0442 \u0441\u0430\u043C\u0443\u044E \u0432\u044B\u0441\u043E\u043A\u0443\u044E \u0441\u0442\u0430\u0432\u043A\u0443, \u0432\u044B \u0438\u0434\u0451\u0442\u0435 \u0432\u0430-\u0431\u0430\u043D\u043A \u0438 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442\u0435 \u0442\u043E\u0440\u0433\u0438.",
              "Tab: \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u043E\u0442\u043A\u0430\u0437\u0443 \u043E\u0442 \u044D\u0442\u043E\u0439 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438.",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0430 \u0432\u043D\u0438\u0437 \u0438\u0437 \u0432\u043E\u043F\u0440\u043E\u0441\u0430: \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u043E\u0442\u0432\u0435\u0442\u0430\u043C. \u0421\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u0432\u0430\u0440\u0438\u0430\u043D\u0442, Enter \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0435\u0433\u043E, \u0435\u0441\u043B\u0438 \u0432\u044B \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u0442\u043E\u0440\u0433\u0438.",
